-- CORTE BITRIX 2026-08-17 13:34 — parte 2 de 3 (9000 deals)
-- Actualiza SOLO: etapa, etapa_bitrix, responsable y fecha de creacion.
-- Ningun otro campo del lead se toca.
-- Si un lead recibio webhook DESPUES del corte, se lo saltea y conserva la
-- etapa nueva que le pusieron. Correr las partes EN ORDEN.


BEGIN;

ON CONFLICT (empresa, bitrix_id) DO UPDATE SET etapa = EXCLUDED.etapa, etapa_bitrix = EXCLUDED.etapa_bitrix, responsible = COALESCE(EXCLUDED.responsible, l.responsible), created_at = EXCLUDED.created_at, updated_at = NOW()
  WHERE NOT EXISTS (
    SELECT 1 FROM public.bitrix_webhook_leads_historial h
    WHERE h.empresa = l.empresa AND h.bitrix_id = l.bitrix_id
      AND h.created_at > TIMESTAMP '2026-08-17 13:34:00' AT TIME ZONE 'America/Guayaquil'
  );

COMMIT;
